class EmptyEnv(MultiGridEnv):
    "This environment is an empty room, and the goal for each agent is to reach the green goal square, which provides a sparse reward."

    def __init__(
        self,
        size: int = 8, # Width and height of the grid
        agent_start_pos: tuple[int, int] | None = (1, 1), # Starting position of the agents (random if None)
        agent_start_dir: Direction | None = Direction.right, # Starting direction of the agents (random if None)
        max_steps: int | None = None, # Maximum number of steps per episode
        joint_reward: bool = False, # Whether all agents receive the reward when the task is completed
        success_termination_mode: str = 'any', # Whether to terminate the environment when any agent reaches the goal or after all agents reach the goal
        **kwargs # See `stable_marl.base.MultiGridEnv.__init__`
    ):
        self.agent_start_pos = agent_start_pos
        self.agent_start_dir = agent_start_dir

        super().__init__(
            mission_space="get to the green goal square",
            grid_size=size,
            max_steps=max_steps or (4 * size**2),
            joint_reward=joint_reward,
            success_termination_mode=success_termination_mode,
            **kwargs,
        )

    def _gen_grid(self, width, height):
        pass

