@patch
def _gen_grid(self: EmptyEnv, width, height):
        # Create an empty grid
        self.grid = Grid(width, height)

        # Generate the surrounding walls
        self.grid.wall_rect(0, 0, width, height)

        # Place a goal square in the bottom-right corner
        self.put_obj(Goal(), width - 2, height - 2)

        # Place the agent
        for agent in self.agents:
            # (without agent overlap, only the first agent uses the fixed start position)
            fixed_start = self.agent_start_pos is not None and self.agent_start_dir is not None
            if fixed_start and (self.allow_agent_overlap or agent.index == 0):
                agent.state.pos = self.agent_start_pos
                agent.state.dir = self.agent_start_dir
            else:
                self.place_agent(agent)

# %% ../../../nbs/envs/multigrid/03_empty.ipynb #f9a0b1c2
@patch
def _variation_factors(self: EmptyEnv) -> dict:
    "The MultiGrid factors, plus `goal.color`."
    factors = MultiGridEnv._variation_factors(self)
    factors['goal'] = {'color': vspaces.Discrete(len(Color), init_value=Color.green.to_index())}
    return factors

